38	SelectorStatus AllReduceAutoSelector::SelectCcuMsAlgo(
39	    const TopoInfoWithNetLayerDetails* topoInfo, const OpParam& opParam,
40	    const std::map<HcclCMDType, std::vector<HcclAlgoType>>& configAlgMap, std::string& selectAlgName) const
41	{
42	    (void)configAlgMap;
43	    HCCL_DEBUG("[AllReduceAutoSelector][%s] start, topoInfo levelNum[%u]", __func__, topoInfo->topoLevelNums);
44	
45	    // 保序模式不支持CCU_MS，需要回退到AICPU
46	    CHK_PRT_RET(
47	        IsNeedStrictModeForOrderPreserved(opParam, topoInfo->userRankSize),
48	        HCCL_DEBUG("[AllReduceAutoSelector] DETERMINISTIC_STRICT mode not supported for CCU_MS, fallback to AICPU."),
49	        SelectorStatus::NOT_MATCH);
50	
51	    if (topoInfo->topoLevelNums > 1) {
52	        HCCL_DEBUG("[AllReduceAutoSelector] levelNum > 1 is not supported yet for ccu_ms mode.");
53	        return SelectorStatus::NOT_MATCH;
54	    }
55	
56	    // MS 模式不支持 int8
57	    CHK_PRT_RET(
58	        opParam.DataDes.dataType == HcclDataType::HCCL_DATA_TYPE_INT8,
59	        HCCL_DEBUG(
60	            "[AllReduceAutoSelector] dataType[%d] is not supported yet for ccu_ms mode.", opParam.DataDes.dataType),
61	        SelectorStatus::NOT_MATCH);
62	
63	    // MS 模式不支持 PROD
64	    CHK_PRT_RET(
65	        opParam.reduceType == HcclReduceOp::HCCL_REDUCE_PROD,
66	        HCCL_DEBUG("[AllReduceAutoSelector] ReduceOp[%d] is not supported yet for ccu_ms mode.", opParam.reduceType),
67	        SelectorStatus::NOT_MATCH);
68	
69	    if (Is64BitDataType(opParam.DataDes.dataType)) {
70	        HCCL_DEBUG("[AllReduceAutoSelector] ccu_ms mode not support INT64, UINT64, FP64.");
71	        return SelectorStatus::NOT_MATCH;
72	    }
73	
74	    return SelectMeshAlgo(topoInfo, opParam, selectAlgName);
75	}
