77	SelectorStatus AllReduceAutoSelector::SelectMeshUBXAlgo(
78	    const TopoInfoWithNetLayerDetails* topoInfo, std::string& selectAlgName, u64 dataSize) const
79	{
80	    // UBX机型
81	    bool isMeshNumEqualToClosNum = false;
82	    bool isClosNumMultipleOfMeshNum = false;
83	    CHK_PRT_RET(
84	        CheckMeshNumEqualToClosNum(topoInfo, isMeshNumEqualToClosNum) != HCCL_SUCCESS,
85	        HCCL_DEBUG("[AllReduceAutoSelector] CheckMeshNumEqualToClosNum failed."), SelectorStatus::NOT_MATCH);
86	    CHK_PRT_RET(
87	        CheckClosNumMultipleOfMeshNum(topoInfo, isClosNumMultipleOfMeshNum) != HCCL_SUCCESS,
88	        HCCL_DEBUG("[AllReduceAutoSelector] CheckClosNumMultipleOfMeshNum failed."), SelectorStatus::NOT_MATCH);
89	    if (isMeshNumEqualToClosNum && topoInfo->userRankSize <= MAX_RANK_NUM_FOR_CONCURRENT_ALGO) {
90	        // 4P mesh
91	        if (IsSmallData(dataSize)) {
92	            // 小数据量，用1d mesh算法
93	            selectAlgName = "CcuMSAllReduceSoleMeshOneShot";
94	        } else {
95	            // 大数据量，用mesh+clos并行算法
96	            selectAlgName = "CcuMSAllReduceConcurMeshNHRMultiLink";
97	        }
98	    } else if (isClosNumMultipleOfMeshNum && !IsSmallData(dataSize)) {
99	        if (dataSize < OMNI_UBX_AR_MS_DATA_SIZE) {
100	            HCCL_DEBUG("[AllReduceAutoSelector][%s] MESH_1D_CLOS not match.", __func__);
101	            return SelectorStatus::NOT_MATCH;
102	        } else {
103	            selectAlgName = "CcuMSAllReducePipeLineMeshNHR";
104	        }
105	    } else if (topoInfo->userRankSize <= MAX_RANK_NUM_FOR_REDUCE_MS_ALGO) {
106	        // 跨4p回退
107	        selectAlgName = "CcuMSAllReduceSoleMesh";
108	    } else {
109	        HCCL_DEBUG("[AllReduceAutoSelector] level0Topo[%u] is not supported mesh yet.", topoInfo->level0Topo);
110	        return SelectorStatus::NOT_MATCH;
111	    }
112	
113	    HCCL_DEBUG("[AllReduceAutoSelector][%s] Algo match [%s]", __func__, selectAlgName.c_str());
114	    return SelectorStatus::MATCH;
115	}
