117	SelectorStatus AllReduceAutoSelector::SelectMeshAlgo(
118	    const TopoInfoWithNetLayerDetails* topoInfo, const OpParam& opParam, std::string& selectAlgName) const
119	{
120	    u64 perDataSize = DATATYPE_SIZE_TABLE[opParam.DataDes.dataType];
121	    u64 dataSize = opParam.DataDes.count * perDataSize;
122	    // 2P场景且数据量大于阈值时回退到AICPU
123	    if (IsTwoLevelNetLayer(topoInfo, opParam) && topoInfo->userRankSize == 2 && dataSize >= AR_2P_DETOUR_DATA_SIZE) {
124	        HCCL_DEBUG(
125	            "[AllReduceAutoSelector] 2P scenario with data size[%llu], "
126	            "fallback to AICPU for better performance.",
127	            dataSize);
128	        return SelectorStatus::NOT_MATCH;
129	    }
130	    if (topoInfo->level0Topo == Level0Shape::MESH_1D) {
131	        if (IsInputOutputOverlap(opParam) == true) { // 不支持 inplace 场景
132	            return SelectorStatus::NOT_MATCH;
133	        }
134	        if (topoInfo->level0MeshType == Level0MeshType::TWO_DIE_REGULAR) {
135	            if (IsSmallData(dataSize)) {
136	                selectAlgName = "CcuMSAllReduceSoleMesh2Die";
137	            } else {
138	                selectAlgName = "CcuMSAllReduceSequenceMesh2Die";
139	            }
140	        } else if (topoInfo->level0MeshType == Level0MeshType::TWO_DIE_NOT_REGULAR) {
141	            HCCL_DEBUG("[AllReduceAutoSelector][%s] TWO_DIE_NOT_REGULAR not match", __func__);
142	            return SelectorStatus::NOT_MATCH;
143	        } else if (IsSmallData(dataSize)) {
144	            selectAlgName = "CcuMSAllReduceSoleMeshOneShot";
145	        } else {
146	            if (IsDevType960() && dataSize > SMALL_COUNT_16M && IsTwoLevelNetLayer(topoInfo, opParam)) {
147	                selectAlgName = "CcuAllReduceSoleMeshMsConcur";
148	            } else {
149	                selectAlgName = "CcuMSAllReduceSoleMesh";
150	            }
151	        }
152	    } else if (topoInfo->level0Topo == Level0Shape::MESH_1D_CLOS) {
153	        if (IsInputOutputOverlap(opParam) == true) {
154	            // 不支持 inplace 场景
155	            return SelectorStatus::NOT_MATCH;
156	        }
157	        return SelectMeshUBXAlgo(topoInfo, selectAlgName, dataSize);
158	    } else {
159	        HCCL_DEBUG("[AllReduceAutoSelector] level0Topo[%u] is not supported yet.", topoInfo->level0Topo);
160	        return SelectorStatus::NOT_MATCH;
161	    }
162	    HCCL_DEBUG("[AllReduceAutoSelector][%s] Algo match [%s]", __func__, selectAlgName.c_str());
163	    return SelectorStatus::MATCH;
164	}
165	
166	SelectorStatus AllReduceAutoSelector::SelectCcuScheduleAlgo(
167	    const TopoInfoWithNetLayerDetails* topoInfo, const OpParam& opParam,
168	    const std::map<HcclCMDType, std::vector<HcclAlgoType>>& configAlgMap, std::string& selectAlgName) const
169	{
170	    (void)configAlgMap;
171	    u32 ccuSize = 64;
172	    HCCL_DEBUG("[AllReduceAutoSelector][%s] start, topoInfo levelNum[%u]", __func__, topoInfo->topoLevelNums);
173	
174	    if (topoInfo->level2Ubg) {
175	        HCCL_INFO(
176	            "[AllReduceAutoSelector][%s] ccu schedule is not supported with level2Ubg, reset to default.", __func__);
177	        return SelectorStatus::NOT_MATCH;
178	    }
179	
180	    if (topoInfo->topoLevelNums >= TOPO_LEVEL_NUM_3) {
181	        HCCL_INFO(
182	            "[AllReduceAutoSelector][%s] ccu schedule is not supported when topoLevelNums >= 3(levelNum[%u]), reset to "
183	            "default.",
184	            __func__, topoInfo->topoLevelNums);
185	        return SelectorStatus::NOT_MATCH;
186	    }
187	
188	    // 保序模式不支持CCU_SCHED，需要回退到AICPU
189	    CHK_PRT_RET(
190	        IsNeedStrictModeForOrderPreserved(opParam, topoInfo->userRankSize),
191	        HCCL_DEBUG("[AllReduceAutoSelector] DETERMINISTIC_STRICT mode not supported for CCU_SCHED, fallback to AICPU."),
192	        SelectorStatus::NOT_MATCH);
193	
194	    // ccu 模式不支持 PROD
195	    CHK_PRT_RET(
196	        opParam.reduceType == HcclReduceOp::HCCL_REDUCE_PROD,
197	        HCCL_DEBUG(
198	            "[AllReduceAutoSelector] ReduceOp[%d] is not supported yet for ccu schedule mode.", opParam.reduceType),
199	        SelectorStatus::NOT_MATCH);
200	
201	    if (Is64BitDataType(opParam.DataDes.dataType)) {
202	        HCCL_DEBUG("[AllReduceAutoSelector] ccu_schedule mode not support INT64, UINT64, FP64.");
203	        return SelectorStatus::NOT_MATCH;
204	    }
205	    u64 perDataSize = DATATYPE_SIZE_TABLE[opParam.DataDes.dataType];
206	    u64 dataSize = opParam.DataDes.count * perDataSize;
207	
208	    if (topoInfo->topoLevelNums > 1) {
209	        if (topoInfo->level0Topo == Level0Shape::MESH_1D) {
210	            CHK_PRT_RET(
211	                IsInputOutputOverlap(opParam) == true,
212	                HCCL_WARNING("[Algo][AllReduceAutoSelector] ccu_sched does not support inplace allreduce."),
213	                SelectorStatus::NOT_MATCH);
214	            // Level1Nhr 已在 CalcTopoShape 中设置（GCD==1 时为 true）
215	            if (topoInfo->Level1Nhr) {
216	                selectAlgName = "CcuSchedAllReduceSoleNHR";
217	                HCCL_INFO("[AllReduceAutoSelector] Level1Nhr=true, select [%s]", selectAlgName.c_str());
218	                return SelectorStatus::MATCH;
219	            } else if (topoInfo->netLayerDetails.localNetInsSizeOfLayer[0] == 1) {
220	                selectAlgName = "CcuSchedAllReduceSoleNHR";
221	            } else if (topoInfo->is2DieFullMesh) {
222	                HCCL_DEBUG("[AllReduceAutoSelector] 2DieFullMesh is not supported yet for ccu schedule mode.");
223	                return SelectorStatus::NOT_MATCH;
224	            } else if (dataSize <= AR_MORE_64P_SEQ_MAX_DATA_SIZE && topoInfo->userRankSize > ccuSize) {
225	                selectAlgName = "CcuSchedAllReduceSequenceMeshMesh";
226	            } else if (
227	                dataSize <= RS_MAX_DATA_SIZE && topoInfo->userRankSize >= ccuSize
228	                && !Is8BitDataType(opParam.DataDes.dataType)) {
229	                selectAlgName = "CcuSchedAllReduceSequenceMeshMesh";
230	                return SelectorStatus::MATCH;
231	            } else if (
232	                dataSize <= AR_FLATTEN_MAX_DATA_SIZE && topoInfo->userRankSize <= ccuSize
233	                && (!IsInputOutputOverlap(opParam)) && !Is8BitDataType(opParam.DataDes.dataType)) {
234	                selectAlgName = "CcuSchedAllReduceSoleMesh";
235	                return SelectorStatus::MATCH;
236	            } else if (
237	                dataSize <= 64 * 1024 * 1024 && topoInfo->userRankSize < ccuSize
238	                && !Is8BitDataType(opParam.DataDes.dataType)) {
239	                selectAlgName = "CcuSchedAllReduceSequenceMeshMesh";
240	                return SelectorStatus::MATCH;
241	            } else if (IsSmallDataCCU(dataSize, topoInfo->userRankSize)) { // 64M以下跑ccu
242	                // 性能优化改用MS做reduce后不支持int8
243	                CHK_PRT_RET(
244	                    opParam.DataDes.dataType == HcclDataType::HCCL_DATA_TYPE_INT8,
245	                    HCCL_DEBUG(
246	                        "[AllReduceAutoSelector] dataType[%d] is not supported yet for ccu schedule mode with ms "
247	                        "reduce. levelNum[%u]",
248	                        opParam.DataDes.dataType, topoInfo->topoLevelNums),
249	                    SelectorStatus::NOT_MATCH);
250	                selectAlgName = "CcuSchedAllReduceParallelMeshNHR";
251	                return SelectorStatus::MATCH;
252	            } else {
253	                return SelectorStatus::NOT_MATCH; // 64M以上切为aicpu
254	            }
255	        } else if (topoInfo->level0Topo == Level0Shape::CLOS && (!IsInputOutputOverlap(opParam))) {
256	            if (dataSize < AR_CCU_CLOS_1D_SMALL_DATA_SIZE) {
257	                selectAlgName = "CcuSchedAllReduceSoleNHR";
258	                return SelectorStatus::MATCH;
259	            } else {
260	                return SelectorStatus::NOT_MATCH;
261	            }
262	        } else {
263	            HCCL_DEBUG(
264	                "[AllReduceAutoSelector] level0Topo[%d] is not supported yet for ccu schedule mode.",
265	                topoInfo->level0Topo);
266	            return SelectorStatus::NOT_MATCH;
267	        }
268	    } else {
269	        return SelectCcuScheduleLevel0Algo(topoInfo, opParam, selectAlgName, dataSize);
270	    }
271	    HCCL_DEBUG("[AllReduceAutoSelector][%s] Algo match [%s]", __func__, selectAlgName.c_str());
272	    return SelectorStatus::MATCH;
273	}
