275	SelectorStatus AllReduceAutoSelector::SelectCcuScheduleLevel0UBXAlgo(
276	    const TopoInfoWithNetLayerDetails* topoInfo, std::string& selectAlgName, const u64 dataSize) const
277	{
278	    // UBX机型
279	    bool isMeshNumEqualToClosNum = false;
280	    bool isClosNumMultipleOfMeshNum = false;
281	    CHK_PRT_RET(
282	        CheckMeshNumEqualToClosNum(topoInfo, isMeshNumEqualToClosNum) != HCCL_SUCCESS,
283	        HCCL_DEBUG("[AllReduceAutoSelector] CheckMeshNumEqualToClosNum failed."), SelectorStatus::NOT_MATCH);
284	    CHK_PRT_RET(
285	        CheckClosNumMultipleOfMeshNum(topoInfo, isClosNumMultipleOfMeshNum) != HCCL_SUCCESS,
286	        HCCL_DEBUG("[AllReduceAutoSelector] CheckClosNumMultipleOfMeshNum failed."), SelectorStatus::NOT_MATCH);
287	    if (isMeshNumEqualToClosNum && topoInfo->userRankSize <= MAX_RANK_NUM_FOR_CONCURRENT_ALGO) {
288	        // 4P mesh
289	        if (IsSmallData(dataSize)) {
290	            // 小数据量，用1d mesh算法
291	            selectAlgName = "CcuSchedAllReduceSoleMesh";
292	        } else {
293	            // 大数据量，用mesh+clos并行算法
294	            selectAlgName = "CcuSchedAllReduceConcurMeshNHRMultiLink";
295	        }
296	    } else if (isClosNumMultipleOfMeshNum && !IsSmallData(dataSize)) {
297	        // 矩形场景大数据量，用Parallel并行算法
298	        if (dataSize < OMNI_UBX_AR_SCHED_DATA_SIZE) {
299	            selectAlgName = "CcuAllReduceParallelNHR1DMutiJetty";
300	        } else {
301	            selectAlgName = "CcuSchedAllReducePipeLineMeshNHR";
302	        }
303	    } else {
304	        // 其他场景，用1d NHR算法
305	        selectAlgName = "CcuSchedAllReduceSoleNHRMultiLink";
306	    }
307	
308	    HCCL_DEBUG("[AllReduceAutoSelector][%s] Algo match [%s]", __func__, selectAlgName.c_str());
309	    return SelectorStatus::MATCH;
310	}
