312	SelectorStatus AllReduceAutoSelector::SelectCcuScheduleLevel0AlgoMesh1D(
313	    const TopoInfoWithNetLayerDetails* topoInfo, const OpParam& opParam, std::string& selectAlgName,
314	    const u64 dataSize) const
315	{
316	    // 性能优化改用MS做reduce后不支持int8
317	    CHK_PRT_RET(
318	        opParam.DataDes.dataType == HcclDataType::HCCL_DATA_TYPE_INT8,
319	        HCCL_DEBUG(
320	            "[AllReduceAutoSelector] dataType[%d] is not supported yet for ccu schedule mode "
321	            "with ms reduce.",
322	            opParam.DataDes.dataType),
323	        SelectorStatus::NOT_MATCH);
324	    double ratio;
325	    if (topoInfo->userRankSize == 0) {
326	        HCCL_DEBUG("[AllReduceAutoSelector] the selector userRankSize not set");
327	        ratio = 1;
328	    } else {
329	        ratio = DEFAULT_RANK_SIZE / topoInfo->userRankSize / topoInfo->userRankSize;
330	    }
331	    if (dataSize * ratio > AR_M2M_1D_MAX_DATA_SIZE) {
332	        return SelectorStatus::NOT_MATCH;
333	    }
334	    if (topoInfo->level0MeshType == Level0MeshType::TWO_DIE_REGULAR) {
335	        if (IsSmallData(dataSize)) {
336	            selectAlgName = "CcuSchedAllReduceSoleMesh2Die";
337	        } else {
338	            selectAlgName = "CcuSchedAllReduceSequenceMesh2Die";
339	        }
340	    } else if (topoInfo->level0MeshType == Level0MeshType::TWO_DIE_NOT_REGULAR) {
341	        HCCL_DEBUG("[AllReduceAutoSelector][%s] TWO_DIE_NOT_REGULAR not match", __func__);
342	        return SelectorStatus::NOT_MATCH;
343	    } else {
344	        selectAlgName = "CcuSchedAllReduceSoleMesh";
345	    }
346	    HCCL_DEBUG("[AllReduceAutoSelector][%s] Algo match [%s]", __func__, selectAlgName.c_str());
347	    return SelectorStatus::MATCH;
348	}
