350	SelectorStatus AllReduceAutoSelector::SelectCcuScheduleLevel0Algo(
351	    const TopoInfoWithNetLayerDetails* topoInfo, const OpParam& opParam, std::string& selectAlgName,
352	    const u64 dataSize) const
353	{
354	    // ccu 模式不支持 inplace 场景
355	    CHK_PRT_RET(
356	        IsInputOutputOverlap(opParam) == true,
357	        HCCL_WARNING("[Algo][AllReduceAutoSelector] ccu_sched does not support inplace allreduce."),
358	        SelectorStatus::NOT_MATCH);
359	    if (topoInfo->level0Topo == Level0Shape::MESH_1D) {
360	        return SelectCcuScheduleLevel0AlgoMesh1D(topoInfo, opParam, selectAlgName, dataSize);
361	    } else if (topoInfo->level0Topo == Level0Shape::MESH_1D_CLOS) {
362	        if (topoInfo->level0PcieMix) {
363	            if (IsLayerAllConnetedWithTopo(topoInfo, 0, CommTopo::COMM_TOPO_1DMESH)) {
364	                return SelectCcuScheduleLevel0AlgoMesh1D(topoInfo, opParam, selectAlgName, dataSize);
365	            } else {
366	                // PCIE-SW定制机型，Mesh无法链接全卡时，需要跨pcie链路，不支持ccu模式
367	                HCCL_WARNING("[AllReduceAutoSelector] pcie mixed topo is not supported yet for ccu schedule mode.");
368	                return SelectorStatus::NOT_MATCH;
369	            }
370	        } else {
371	            CHK_PRT_RET(
372	                opParam.DataDes.dataType == HcclDataType::HCCL_DATA_TYPE_INT8,
373	                HCCL_DEBUG(
374	                    "[AllReduceAutoSelector] dataType[%d] is not supported yet for ccu schedule mode. "
375	                    "with ms reduce.",
376	                    opParam.DataDes.dataType),
377	                SelectorStatus::NOT_MATCH);
378	            return SelectCcuScheduleLevel0UBXAlgo(topoInfo, selectAlgName, dataSize);
379	        }
380	    } else if (topoInfo->level0Topo == Level0Shape::CLOS) {
381	        if (topoInfo->level0PcieMix) {
382	            // PCIE-SW定制机型，Mesh无法链接全卡时，需要跨pcie链路，不支持ccu模式
383	            HCCL_WARNING("[AllReduceAutoSelector] pcie mixed topo is not supported yet for ccu schedule mode.");
384	            return SelectorStatus::NOT_MATCH;
385	        }
386	        if (dataSize < AR_CCU_CLOS_1D_SMALL_DATA_SIZE) {
387	            selectAlgName = "CcuSchedAllReduceSoleNHR";
388	            return SelectorStatus::MATCH;
389	        } else {
390	            return SelectorStatus::NOT_MATCH;
391	        }
392	    } else {
393	        HCCL_DEBUG(
394	            "[AllReduceAutoSelector] level0Topo[%d] is not supported yet for ccu schedule mode.", topoInfo->level0Topo);
395	        return SelectorStatus::NOT_MATCH;
396	    }
397	    HCCL_DEBUG("[AllReduceAutoSelector][%s] Algo match [%s]", __func__, selectAlgName.c_str());
398	    return SelectorStatus::MATCH;
399	}
