489	                                                                           "AicpuAllReduceSoleMeshTwoShot";
490	        } else if (dataSize <= AR_AICPU_1D_SMALL_DATA_SIZE) {
491	            selectAlgName = "AicpuAllReduceSoleMeshOneShot";
492	        } else {
493	            // 大数据量，用mesh+clos并行算法
494	            selectAlgName = "AicpuAllReduceConcurMeshTwoShotNHR";
495	        }
496	    } else if (isDataTypeOrReduceTypeSpecial) {
497	        selectAlgName = "AicpuAllReduceSoleNHRAicpuReduce";
498	    } else if (isClosNumMultipleOfMeshNum && !IsSmallData(dataSize)) {
499	        // 矩形场景大数据量，用Parallel并行算法
500	        selectAlgName = "InsAllReduceParallelRSAGUBX";
501	    } else {
502	        // 其他场景，用1d NHR算法
503	        selectAlgName = "AicpuAllReduceSoleNHR";
504	    }
505	
506	    HCCL_DEBUG("[AllReduceAutoSelector][%s] Algo match [%s]", __func__, selectAlgName.c_str());
507	    return SelectorStatus::MATCH;
