17	SelectorStatus
18	AutoSelectorBase::Select(OpParam& opParam, TopoInfoWithNetLayerDetails* topoInfo, std::string& selectAlgName) const
19	{
20	    HCCL_DEBUG("[AutoSelectorBase][%s] start, OpExecuteConfig is %d.", __func__, opParam.opExecuteConfig);
21	    std::map<HcclCMDType, std::vector<HcclAlgoType>> configAlgMap = GetExternalInputHcclAlgoConfigAllType();
22	    SelectorStatus ret = SelectorStatus::NOT_MATCH;
23	    bool hostDPUOnly = false;
24	    if ((CheckHostDPUOnly(opParam.hcclComm, topoInfo, hostDPUOnly) == HCCL_SUCCESS) && hostDPUOnly) {
25	        opParam.opExecuteConfig = OpExecuteConfig::HOSTCPU;
26	        opParam.engine = CommEngine::COMM_ENGINE_CPU;
27	        return SelectDPUAlgo(topoInfo, opParam, configAlgMap, selectAlgName);
28	    }
29	    if (opParam.opExecuteConfig == OpExecuteConfig::CCU_MS) {
30	        ret = SelectCcuMsAlgo(topoInfo, opParam, configAlgMap, selectAlgName);
31	        if (ret == SelectorStatus::NOT_MATCH) {
32	            opParam.opExecuteConfig = OpExecuteConfig::CCU_SCHED;
33	        } else {
34	            return ret;
35	        }
36	    }
37	    if (opParam.opExecuteConfig == OpExecuteConfig::CCU_SCHED) {
38	        ret = SelectCcuScheduleAlgo(topoInfo, opParam, configAlgMap, selectAlgName);
39	        if (ret == SelectorStatus::NOT_MATCH) {
40	            opParam.opExecuteConfig = OpExecuteConfig::CCU_FAIL;
41	        } else {
42	            return ret;
43	        }
44	    }
45	    if (ProcessAivConfig(opParam, topoInfo, configAlgMap, selectAlgName, ret)) {
46	        return ret;
47	    }
48	    if (IsStarsState(opParam.opExecuteConfig)) {
49	        // 需要回退AIV的场景下，回退AIV算法
50	        if (IsRollBackAiv(opParam, topoInfo)) {
51	            HCCL_INFO("[Algo][AutoSelectorBase] Need to roll back AIV algo");
52	            opParam.opExecuteConfig = OpExecuteConfig::AIV_ONLY;
53	            (void)ProcessAivConfig(opParam, topoInfo, configAlgMap, selectAlgName, ret);
54	            HCCL_INFO(
55	                "[Algo][AutoSelectorBase] The selected algo is %s, OpExecuteConfig is %d.", selectAlgName.c_str(),
56	                opParam.opExecuteConfig);
57	            return ret;
58	        }
59	        ret = SelectAicpuAlgo(topoInfo, opParam, configAlgMap, selectAlgName);
60	        if (ret == SelectorStatus::MATCH) {
61	            opParam.opExecuteConfig = OpExecuteConfig::AICPU_TS;
62	        }
63	    }
64	    HCCL_INFO(
65	        "[Algo][AutoSelectorBase] The selected algo is %s, OpExecuteConfig is %d.", selectAlgName.c_str(),
66	        opParam.opExecuteConfig);
67	    return ret;
68	}
