315	        HCCL_INFO("[Algo][AutoSelectorBase][IsInputOutputOverlap] The input or output buffer is null. Not overlap."),
316	        false);
317	
318	    u64 inputDataSize = opParam.inputSize;
319	    u64 outputDataSize = opParam.outputSize;
320	
321	    CHK_PRT_RET(
322	        inputDataSize == 0 || outputDataSize == 0,
323	        // 不存在overlap情况
324	        HCCL_INFO("[Algo][AutoSelectorBase][IsInputOutputOverlap] The input or output buffer size is 0. Not overlap."),
325	        false);
326	
327	    uintptr_t inputStart = reinterpret_cast<uintptr_t>(opParam.inputPtr);
328	    uintptr_t outputStart = reinterpret_cast<uintptr_t>(opParam.outputPtr);
329	    uintptr_t inputEnd = inputStart + inputDataSize - 1;
330	    uintptr_t outputEnd = outputStart + outputDataSize - 1;
331	
332	    HCCL_DEBUG(
333	        "[Algo][AutoSelectorBase][IsInputOutputOverlap] inputStart[%llu], inputEnd[%llu], outputStart[%llu], "
334	        "outputEnd[%llu].",
335	        inputStart, inputEnd, outputStart, outputEnd);
336	
337	    CHK_PRT_RET(
338	        inputStart <= outputEnd && outputStart <= inputEnd,
339	        HCCL_INFO(
340	            "[Algo][AutoSelectorBase][IsInputOutputOverlap] inputStart[%llu], inputEnd[%llu], outputStart[%llu], "
341	            "outputEnd[%llu]. Overlap detected.",
342	            inputStart, inputEnd, outputStart, outputEnd),
343	        true);
344	
345	    HCCL_DEBUG("[Algo][AutoSelectorBase][IsInputOutputOverlap]No overlap between input and output memory.");
346	    return false;
347	}
